package com.starwake.core.gfx

import com.starwake.core.math.withAlpha
import java.nio.ByteBuffer
import java.nio.ByteOrder
import kotlin.math.sqrt

/**
 * Glyph metrics of the signed-distance-field UI font atlas (generated by tools/gen_font.py).
 * The atlas holds several faces: [UI] (Titillium Web), [TITLE] (Sarpanch), [MONO] (Roboto Mono).
 */
class FontData(
    val baseSize: Float,
    val spread: Float,
    val atlasW: Int,
    val atlasH: Int,
    private val caps: FloatArray,
    private val keys: IntArray,
    private val gx: FloatArray,
    private val gy: FloatArray,
    private val gw: FloatArray,
    private val gh: FloatArray,
    private val xoff: FloatArray,
    private val yoff: FloatArray,
    private val adv: FloatArray,
) {
    private val ascii = IntArray(FACES * 128) { -1 }

    init {
        for (i in keys.indices) {
            val face = keys[i] ushr 16
            val code = keys[i] and 0xFFFF
            if (code < 128 && face < FACES) ascii[face * 128 + code] = i
        }
    }

    fun capHeight(face: Int): Float = caps[face.coerceIn(0, caps.size - 1)]

    /** Glyph index for [code] in [face], or -1. */
    fun index(face: Int, code: Int): Int {
        if (code < 128 && face < FACES) return ascii[face * 128 + code]
        val key = (face shl 16) or code
        var lo = 0
        var hi = keys.size - 1
        while (lo <= hi) {
            val mid = (lo + hi) ushr 1
            val c = keys[mid]
            if (c < key) lo = mid + 1 else if (c > key) hi = mid - 1 else return mid
        }
        return -1
    }

    fun advance(i: Int) = adv[i]
    fun x(i: Int) = gx[i]
    fun y(i: Int) = gy[i]
    fun w(i: Int) = gw[i]
    fun h(i: Int) = gh[i]
    fun xOff(i: Int) = xoff[i]
    fun yOff(i: Int) = yoff[i]

    companion object {
        const val UI = 0
        const val TITLE = 1
        const val MONO = 2
        const val FACES = 3

        /** Parses the text metrics file. */
        fun parse(text: String): FontData {
            var base = 48f
            var spread = 6f
            var w = 1024
            var h = 1024
            val caps = FloatArray(FACES) { 34f }
            val rows = ArrayList<FloatArray>()
            for (line in text.lineSequence()) {
                val parts = line.trim().split(' ').filter { it.isNotEmpty() }
                if (parts.isEmpty()) continue
                when (parts[0]) {
                    "info" -> for (p in parts.drop(1)) {
                        val (k, v) = p.split('=')
                        when (k) {
                            "base" -> base = v.toFloat()
                            "spread" -> spread = v.toFloat()
                            "width" -> w = v.toInt()
                            "height" -> h = v.toInt()
                        }
                    }
                    "face" -> {
                        val face = parts[1].toInt()
                        if (face < FACES) caps[face] = parts[2].substringAfter('=').toFloat()
                    }
                    "g" -> rows.add(FloatArray(9) { parts[it + 1].toFloat() })
                }
            }
            val n = rows.size
            val key = { r: FloatArray -> (r[0].toInt() shl 16) or r[1].toInt() }
            rows.sortBy { key(it) }
            return FontData(
                base, spread, w, h, caps,
                IntArray(n) { key(rows[it]) },
                FloatArray(n) { rows[it][2] }, FloatArray(n) { rows[it][3] },
                FloatArray(n) { rows[it][4] }, FloatArray(n) { rows[it][5] },
                FloatArray(n) { rows[it][6] }, FloatArray(n) { rows[it][7] },
                FloatArray(n) { rows[it][8] },
            )
        }

        /** Reads the binary SDF atlas: "SDF1", int32 width, int32 height, then width*height bytes. */
        fun atlasPixels(bytes: ByteArray): Triple<Int, Int, ByteBuffer> {
            val bb = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
            val magic = ByteArray(4)
            bb.get(magic)
            require(String(magic, Charsets.US_ASCII) == "SDF1") { "bad font atlas" }
            val w = bb.int
            val h = bb.int
            val px = Buffers.bytes(w * h)
            px.put(bytes, 12, w * h)
            px.position(0)
            return Triple(w, h, px)
        }
    }
}

/**
 * Batched 2D renderer for the HUD and menus: anti-aliased rounded/chamfered boxes, rings and SDF
 * text, all in a single shader and (normally) a single draw call per frame.
 */
class UiRenderer(private val gl: Gl, val font: FontData, atlas: ByteArray) {
    private val program = ShaderProgram(gl, "ui", Shaders.uiVs, Shaders.uiFs)
    private val uScreen = program.u("u_screen")
    private val uFont = program.u("u_font")
    private val stream = QuadStream(
        gl, 2500,
        intArrayOf(2, GL.FLOAT, 2, GL.FLOAT, 4, GL.UNSIGNED_BYTE, 4, GL.FLOAT, 4, GL.FLOAT),
    )
    private val fontTex: Int
    private var screenW = 1f
    private var screenH = 1f

    init {
        val (w, h, px) = FontData.atlasPixels(atlas)
        fontTex = gl.genTexture()
        gl.bindTexture(GL.TEXTURE_2D, fontTex)
        gl.pixelStorei(GL.UNPACK_ALIGNMENT, 1)
        gl.texImage2D(GL.TEXTURE_2D, 0, GL.R8, w, h, GL.RED, GL.UNSIGNED_BYTE, px)
        gl.texParameteri(GL.TEXTURE_2D, GL.TEXTURE_MIN_FILTER, GL.LINEAR)
        gl.texParameteri(GL.TEXTURE_2D, GL.TEXTURE_MAG_FILTER, GL.LINEAR)
        gl.texParameteri(GL.TEXTURE_2D, GL.TEXTURE_WRAP_S, GL.CLAMP_TO_EDGE)
        gl.texParameteri(GL.TEXTURE_2D, GL.TEXTURE_WRAP_T, GL.CLAMP_TO_EDGE)
        gl.pixelStorei(GL.UNPACK_ALIGNMENT, 4)
    }

    fun begin(width: Int, height: Int) {
        screenW = width.toFloat()
        screenH = height.toFloat()
        stream.begin()
    }

    fun end() {
        if (stream.quads == 0) return
        gl.disable(GL.DEPTH_TEST)
        gl.disable(GL.CULL_FACE)
        gl.enable(GL.BLEND)
        gl.blendFunc(GL.SRC_ALPHA, GL.ONE_MINUS_SRC_ALPHA)
        program.use()
        gl.uniform2f(uScreen, screenW, screenH)
        gl.activeTexture(GL.TEXTURE0)
        gl.bindTexture(GL.TEXTURE_2D, fontTex)
        gl.uniform1i(uFont, 0)
        stream.flush()
        gl.disable(GL.BLEND)
    }

    private fun flushIfFull() {
        if (!stream.hasRoom()) {
            // keep going with a new batch rather than dropping UI
            val w = screenW.toInt()
            val h = screenH.toInt()
            end()
            begin(w, h)
        }
    }

    private fun vertex(
        x: Float, y: Float, lx: Float, ly: Float, color: Int,
        p0x: Float, p0y: Float, p0z: Float, p0w: Float, p1x: Float, p1y: Float,
    ) {
        val d = stream.staging
        var c = stream.cursor
        d[c++] = x.toRawBits()
        d[c++] = y.toRawBits()
        d[c++] = lx.toRawBits()
        d[c++] = ly.toRawBits()
        d[c++] = color
        d[c++] = p0x.toRawBits()
        d[c++] = p0y.toRawBits()
        d[c++] = p0z.toRawBits()
        d[c++] = p0w.toRawBits()
        d[c++] = p1x.toRawBits()
        d[c++] = p1y.toRawBits()
        d[c++] = 0
        d[c++] = 0
        stream.cursor = c
    }

    /**
     * Filled or outlined box. [radius] > 0 rounds the corners, < 0 cuts them (chamfer).
     * [stroke] > 0 draws only an outline of that width. [soft] widens the anti-aliasing edge (glows).
     */
    fun rect(x: Float, y: Float, w: Float, h: Float, color: Int, radius: Float = 0f, stroke: Float = 0f, soft: Float = 1f) {
        if ((color ushr 24) == 0) return
        flushIfFull()
        val hw = w * 0.5f
        val hh = h * 0.5f
        val cx = x + hw
        val cy = y + hh
        val pad = soft + 1f
        val col = QuadStream.abgr(color)
        val ex = hw + pad
        val ey = hh + pad
        vertex(cx - ex, cy - ey, -ex, -ey, col, 1f, hw, hh, radius, stroke, soft)
        vertex(cx + ex, cy - ey, ex, -ey, col, 1f, hw, hh, radius, stroke, soft)
        vertex(cx - ex, cy + ey, -ex, ey, col, 1f, hw, hh, radius, stroke, soft)
        vertex(cx + ex, cy + ey, ex, ey, col, 1f, hw, hh, radius, stroke, soft)
        stream.endQuad()
    }

    fun circle(cx: Float, cy: Float, r: Float, color: Int, stroke: Float = 0f, soft: Float = 1f) {
        if ((color ushr 24) == 0) return
        flushIfFull()
        val e = r + soft + 1f
        val col = QuadStream.abgr(color)
        vertex(cx - e, cy - e, -e, -e, col, 2f, r, 0f, 0f, stroke, soft)
        vertex(cx + e, cy - e, e, -e, col, 2f, r, 0f, 0f, stroke, soft)
        vertex(cx - e, cy + e, -e, e, col, 2f, r, 0f, 0f, stroke, soft)
        vertex(cx + e, cy + e, e, e, col, 2f, r, 0f, 0f, stroke, soft)
        stream.endQuad()
    }

    /**
     * An anti-aliased isosceles triangle of base [width] and height [length] centred on ([cx], [cy]),
     * its tip pointing up and the whole turned [angle] radians clockwise (screen Y down: 0 = tip up,
     * π/2 = tip right). [half] draws only the triangle's left (-1) or right (+1) half, cut hard
     * along its axis so two halves of different colours meet without a seam; 0 draws it whole.
     */
    fun triangle(cx: Float, cy: Float, width: Float, length: Float, angle: Float, color: Int, half: Int = 0, soft: Float = 1f) {
        if ((color ushr 24) == 0) return
        flushIfFull()
        val hw = width * 0.5f
        val hh = length * 0.5f
        val pad = soft + 1f
        val ex = hw + pad
        val ey = hh + pad
        val c = kotlin.math.cos(angle)
        val s = kotlin.math.sin(angle)
        val col = QuadStream.abgr(color)
        val sel = half.toFloat()
        // local (lx, ly) → screen (cx + lx·c − ly·s, cy + lx·s + ly·c): clockwise on a Y-down screen
        vertex(cx - ex * c + ey * s, cy - ex * s - ey * c, -ex, -ey, col, 3f, hw, length, sel, 0f, soft)
        vertex(cx + ex * c + ey * s, cy + ex * s - ey * c, ex, -ey, col, 3f, hw, length, sel, 0f, soft)
        vertex(cx - ex * c - ey * s, cy - ex * s + ey * c, -ex, ey, col, 3f, hw, length, sel, 0f, soft)
        vertex(cx + ex * c - ey * s, cy + ex * s + ey * c, ex, ey, col, 3f, hw, length, sel, 0f, soft)
        stream.endQuad()
    }

    fun line(x0: Float, y0: Float, x1: Float, y1: Float, width: Float, color: Int) {
        if ((color ushr 24) == 0) return
        val dx = x1 - x0
        val dy = y1 - y0
        val len = sqrt(dx * dx + dy * dy)
        if (len < 1e-3f) return
        flushIfFull()
        val ux = dx / len
        val uy = dy / len
        val nx = -uy
        val ny = ux
        val hl = len * 0.5f
        val hw = width * 0.5f
        val cx = (x0 + x1) * 0.5f
        val cy = (y0 + y1) * 0.5f
        val el = hl + 2f
        val ew = hw + 2f
        val col = QuadStream.abgr(color)
        vertex(cx - ux * el - nx * ew, cy - uy * el - ny * ew, -el, -ew, col, 1f, hl, hw, 0f, 0f, 1f)
        vertex(cx + ux * el - nx * ew, cy + uy * el - ny * ew, el, -ew, col, 1f, hl, hw, 0f, 0f, 1f)
        vertex(cx - ux * el + nx * ew, cy - uy * el + ny * ew, -el, ew, col, 1f, hl, hw, 0f, 0f, 1f)
        vertex(cx + ux * el + nx * ew, cy + uy * el + ny * ew, el, ew, col, 1f, hl, hw, 0f, 0f, 1f)
        stream.endQuad()
    }

    fun textWidth(s: CharSequence, size: Float, tracking: Float = 0f, face: Int = FontData.UI): Float {
        val scale = size / font.baseSize
        var w = 0f
        val n = s.length
        for (i in 0 until n) {
            val g = font.index(face, s[i].code)
            w += if (g >= 0) font.advance(g) * scale else size * 0.3f
            if (i < n - 1) w += tracking * size
        }
        return w
    }

    /** Height from baseline to the top of capital letters, for vertical centring. */
    fun capHeight(size: Float, face: Int = FontData.UI): Float = font.capHeight(face) * size / font.baseSize

    /**
     * Draws text with its baseline at [y]. [align]: 0 left, 1 centre, 2 right.
     * [weight] > 0 makes glyphs bolder (SDF threshold shift). Returns the text width.
     */
    fun text(
        s: CharSequence, x: Float, y: Float, size: Float, color: Int,
        align: Int = LEFT, tracking: Float = 0f, weight: Float = 0f, shadow: Float = 0f, face: Int = FontData.UI,
    ): Float {
        val width = textWidth(s, size, tracking, face)
        var pen = when (align) {
            CENTER -> x - width * 0.5f
            RIGHT -> x - width
            else -> x
        }
        if (shadow > 0f) {
            glyphs(s, pen, y + size * 0.06f, size, withAlpha(0xFF000000.toInt(), shadow), tracking, weight + 0.08f, 0.35f, face)
        }
        glyphs(s, pen, y, size, color, tracking, weight, 1f, face)
        return width
    }

    /** Text vertically centred on [cy]. */
    fun textCentered(
        s: CharSequence, cx: Float, cy: Float, size: Float, color: Int,
        align: Int = CENTER, tracking: Float = 0f, weight: Float = 0f, shadow: Float = 0f, face: Int = FontData.UI,
    ): Float = text(s, cx, cy + capHeight(size, face) * 0.5f, size, color, align, tracking, weight, shadow, face)

    private fun glyphs(s: CharSequence, x: Float, y: Float, size: Float, color: Int, tracking: Float, weight: Float, sharp: Float, face: Int) {
        if ((color ushr 24) == 0) return
        val scale = size / font.baseSize
        val sdfScale = 2f * font.spread * scale * sharp
        val iw = 1f / font.atlasW
        val ih = 1f / font.atlasH
        val col = QuadStream.abgr(color)
        var pen = x
        for (i in 0 until s.length) {
            val g = font.index(face, s[i].code)
            if (g < 0) {
                pen += size * 0.3f + tracking * size
                continue
            }
            val gw = font.w(g)
            if (gw > 0f) {
                flushIfFull()
                val x0 = pen + font.xOff(g) * scale
                val y0 = y + font.yOff(g) * scale
                val x1 = x0 + gw * scale
                val y1 = y0 + font.h(g) * scale
                val u0 = font.x(g) * iw
                val v0 = font.y(g) * ih
                val u1 = (font.x(g) + gw) * iw
                val v1 = (font.y(g) + font.h(g)) * ih
                vertex(x0, y0, u0, v0, col, 0f, sdfScale, weight, 0f, 0f, 1f)
                vertex(x1, y0, u1, v0, col, 0f, sdfScale, weight, 0f, 0f, 1f)
                vertex(x0, y1, u0, v1, col, 0f, sdfScale, weight, 0f, 0f, 1f)
                vertex(x1, y1, u1, v1, col, 0f, sdfScale, weight, 0f, 0f, 1f)
                stream.endQuad()
            }
            pen += font.advance(g) * scale + tracking * size
        }
    }

    fun dispose() {
        program.dispose()
        stream.dispose()
        gl.deleteTexture(fontTex)
    }

    companion object {
        const val LEFT = 0
        const val CENTER = 1
        const val RIGHT = 2
    }
}
